"""Generates internal/calendar/windowstz_table.go from icalendar's WINDOWS_TO_OLSON (the Windows time zone ids
Outlook writes as TZID). Run inside `nix develop --impure`: python tools/calendar/gen_windows_tz.py"""

from pathlib import Path

from icalendar.timezone.windows_to_olson import WINDOWS_TO_OLSON

OUT = Path(__file__).resolve().parents[2] / "internal" / "calendar" / "windowstz_table.go"


def main():
    lines = [
        "// Code generated by tools/calendar/gen_windows_tz.py; DO NOT EDIT.",
        "",
        "package calendar",
        "",
        "var windowsToOlson = map[string]string{",
    ]
    for name in sorted(WINDOWS_TO_OLSON):
        lines.append(f'\t"{name}": "{WINDOWS_TO_OLSON[name]}",')
    lines += ["}", ""]
    OUT.write_text("\n".join(lines))


if __name__ == "__main__":
    main()
